1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	};
49	
50	const quote = (step: QuoteStep): StepResult => {
51	  const basePremium = step.items.reduce(
52	    (sum, item) => sum + BASE_PREMIUMS[item.type],
53	    0,
54	  );
55	  const premium =
56	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
57	
58	  return { premium };
59	};
60	
61	export const runScenario = (scenario: Scenario): ScenarioResult => {
62	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
63	};
